UPDATE staff_profile
staff_no = #{staffNo}, staff_type = #{staffType}, title = #{title}, specialty = #{specialty}, introduction = #{introduction}, max_daily_appointments = #{maxDailyAppointments}, status = #{status}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT sp.id, sp.user_id, sp.staff_no, su.real_name, su.phone, sp.staff_type, sp.title, sp.specialty, sp.introduction, sp.max_daily_appointments, sp.status FROM staff_profile sp LEFT JOIN sys_user su ON sp.user_id = su.id WHERE 1=1
AND (su.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR sp.staff_no LIKE CONCAT('%', #{query.keyword}, '%') OR su.phone LIKE CONCAT('%', #{query.keyword}, '%'))
AND sp.staff_type = #{query.staffType}
AND sp.status = #{query.status}
ORDER BY sp.create_time DESC LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*) FROM staff_profile sp LEFT JOIN sys_user su ON sp.user_id = su.id WHERE 1=1
AND (su.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR sp.staff_no LIKE CONCAT('%', #{query.keyword}, '%') OR su.phone LIKE CONCAT('%', #{query.keyword}, '%'))
AND sp.staff_type = #{query.staffType}
AND sp.status = #{query.status}

SELECT su.real_name AS label, sp.id AS value FROM staff_profile sp LEFT JOIN sys_user su ON sp.user_id = su.id WHERE sp.status = 1
AND sp.staff_type = #{staffType}
ORDER BY sp.staff_no
